def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape

    # enclosed background: background components not touching the border
    enclosed = np.zeros_like(g, dtype=bool)
    for comp in components(g == bg):
        if not any(y in (0, H - 1) or x in (0, W - 1) for y, x in comp):
            for y, x in comp:
                enclosed[y, x] = True

    out = g.copy()
    for obj in objects(g, bg=bg):
        convex, concave = [], []
        for y, x in obj["cells"]:
            nb = [(dy, dx) for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]
                  if 0 <= y + dy < H and 0 <= x + dx < W and g[y + dy, x + dx] != bg]
            if len(nb) != 2:
                continue
            (a, b), (c, d) = nb
            if a + c == 0 or b + d == 0:
                continue  # straight segment
            yy, xx = y + a + c, x + b + d
            inside = 0 <= yy < H and 0 <= xx < W and enclosed[yy, xx]
            (convex if inside else concave).append((y, x))
        for y, x in convex:
            out[y, x] = 4
        emit(out, f"Loop at rows {obj['box'][0]}-{obj['box'][2]}: outward (convex) corners painted 4")
        if concave:
            for y, x in concave:
                out[y, x] = 2
            emit(out, f"Loop at rows {obj['box'][0]}-{obj['box'][2]}: inward (concave) notch corners painted 2")

    emit(out, "All loop corners recoloured: convex -> 4, concave -> 2; straight runs unchanged")
    return out
